/* ===== Services: category + subcategory multi-select filter (shared component) ===== */
const slug=s=>String(s).toLowerCase().replace(/&/g,' ').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const catSlug=id=>slug(catOf(id).en);
const slugCat=s=>(SCATS.find(c=>catSlug(c.id)===s||c.id===s)||{}).id;
const SSUBS={
 wedding:[['Tent & Lighting','टेंट व लाइटिंग'],['DJ & Sound','डीजे व साउंड सिस्टम'],['Catering','खान-पान व केटरिंग सेवा'],['Photography & Video','फोटोग्राफी व वीडियोग्राफी'],['Decoration','सजावट'],['Mehndi & Makeup','मेहंदी व मेकअप'],['Band & Baraat','बैंड-बाजा व बारात'],['Invitation Cards','निमंत्रण कार्ड'],['Bridal Wear Rental','दुल्हन के कपड़े किराये पर']],
 builder:[['Mason','राजमिस्त्री'],['Painter','पेंटर'],['Plumber','प्लंबर'],['Electrician','इलेक्ट्रीशियन']],
 mechanic:[['Two-wheeler','दोपहिया वाहन'],['Four-wheeler','चारपहिया वाहन'],['AC Repair','एसी रिपेयर'],['AC Installation','एसी इंस्टॉलेशन'],['Mobile Repair','मोबाइल रिपेयर'],['Appliance Repair','घरेलू उपकरण रिपेयर']],
 education:[['School Coaching','स्कूल कोचिंग'],['Spoken English','स्पोकन इंग्लिश'],['Computer Classes','कंप्यूटर क्लास']],
 electrician:[['House Wiring','घर की वायरिंग'],['Inverter & Battery','इन्वर्टर व बैटरी'],['Appliance Repair','उपकरणों की मरम्मत']],
 plumber:[['Leakage Repair','लीकेज की मरम्मत'],['Bathroom Fitting','बाथरूम फ़िटिंग'],['Tank Cleaning','टंकी की सफ़ाई']],
 other:[['General Services','सामान्य सेवाएँ']]};
function svcSubs(cat){const base=(SSUBS[cat]||[]).map(([en,hi])=>({slug:slug(en),en,hi}));const ex=D().subs.filter(s=>s.main===cat&&s.status==='approved'&&!base.some(b=>b.slug===slug(s.en))).map(s=>({slug:slug(s.en),en:s.en,hi:s.hi}));return [...base,...ex]}
function subInfo(sl){for(const c of SCATS){const f=svcSubs(c.id).find(x=>x.slug===sl);if(f)return{...f,cat:c.id}}return null}
const subLabel=sl=>{const i=subInfo(sl);return i?(S.lang==='hi'&&i.hi?i.hi:i.en):sl};
const subCat=sl=>(subInfo(sl)||{}).cat;
/* seed: provider subcategories + extra wedding providers (idempotent) */
(function(){const d=D();const ss={s1:['tent-lighting','dj-sound','decoration'],s2:['construction','renovation'],s3:['bike-repair','car-repair'],s4:['school-coaching','spoken-english'],s5:['house-wiring','inverter-battery','appliance-repair'],s6:['leakage-repair','bathroom-fitting']};d.svc.forEach(s=>{if(!s.ssubs&&ss[s.id])s.ssubs=ss[s.id]});
 const add=(id,en,hi,area,dx,dy,ph,r,rc,desc,svs,subs)=>{if(d.svc.some(x=>x.id===id))return;const o=mkS(id,en,hi,'wedding',area,dx,dy,ph,r,rc,desc,svs.map((x,i)=>({id:id+'-sv'+i,n:x[0],p:x[1],from:fromNum(x[1]),desc:''})));o.ssubs=subs;o.media=[];o.del={mode:'rider',radius:6,fee:0,min:0,pickup:true,note:''};d.svc.push(o)};
 add('s7','Rocket DJ & Sound','रॉकेट डीजे व साउंड','station',.004,-.006,'9876500107',4.6,44,'DJ, sound system and dance-floor lights for weddings and parties.',[['DJ with sound (6 hrs)','from ₹6,000'],['Dance floor lights','₹2,500']],['dj-sound']);
 add('s8','Annapurna Catering','अन्नपूर्णा केटरिंग','tehsil',-.006,.004,'9876500108',4.7,63,'Pure veg catering for weddings, tilak and parties. Live counters available.',[['Wedding catering','from ₹180 / plate'],['Party snacks','from ₹90 / plate']],['catering']);
 add('s9','Shiv Tent & Lights','शिव टेंट एवं लाइट्स','hata',.009,.002,'9876500109',4.4,38,'Tents, chairs, carpets and decorative lighting on rent.',[['Tent & lighting package','from ₹8,000'],['Chair & table rental','₹6 / chair']],['tent-lighting','decoration']);
 add('s10','Shree Photo & Video','श्री फोटो एवं वीडियो','chauraha',-.001,-.003,'9876500110',4.8,91,'Wedding photography, cinematic video and drone shots.',[['Wedding photography','from ₹15,000'],['Cinematic video','from ₹20,000']],['photography','videography']);
 save()})();
/* state per context */
UI.cf={cats:[],subs:[]};UI.cfId='';UI.pv={cats:[],subs:[]};UI.stx={};UI.sfq={};UI.exLoad=false;
const sfState=ctx=>ctx==='ex'?UI.exF.s:ctx==='srch'?(UI.sfS=UI.sfS||exDef('s')):ctx==='cat'?UI.cf:ctx==='prev'?UI.pv:(UI.stx[ctx]=UI.stx[ctx]||{cats:[],subs:[]});
function svcBaseList(f){let l=[...D().svc,...D().biz.filter(b=>(b.services||[]).length)].filter(x=>x.status==='approved'&&(x.services||[]).length);if(f.dist)l=l.filter(x=>dist(x)<=f.dist);if(f.rating)l=l.filter(x=>x.rating>=f.rating);if(f.avail)l=l.filter(x=>openState(x).open);if(f.verified)l=l.filter(x=>x.verified);if(f.pmin!==''&&f.pmin!==undefined)l=l.filter(x=>minFrom(x)>=+f.pmin);if(f.pmax!==''&&f.pmax!==undefined)l=l.filter(x=>minFrom(x)<=+f.pmax);return l}
function svcApplyCS(l,f){if((f.cats||[]).length)l=l.filter(x=>f.cats.includes(x.cat));if((f.subs||[]).length)l=l.filter(x=>(x.ssubs||[]).some(s=>f.subs.includes(s)));return l}
function exServices(){const f=UI.exF.s;let l=svcApplyCS(svcBaseList(f),f);const so=f.sort;if(so==='rating')l.sort((a,b)=>b.rating-a.rating);else if(so==='distance')l.sort((a,b)=>dist(a)-dist(b));else l.sort((a,b)=>(!!b.featured-!!a.featured)||dist(a)-dist(b));return l}
function svcToggleCat(st,cid,on){st.cats=on?[...new Set([...st.cats,cid])]:st.cats.filter(x=>x!==cid);if(!on)st.subs=st.subs.filter(s=>subCat(s)!==cid)}
function svcSubFilter(ctx,o={}){const st=sfState(ctx),base=sfBase(ctx);let h=`<div class="sf" data-ctx="${ctx}">`;
 if(o.cats)h+=`<div class="sfsec"><h4>${t('Category')}</h4><div class="stack" style="gap:2px">${D().scats.filter(c=>c.on!==false).map(c=>{const n=base.filter(x=>x.cat===c.id).length;return `<label class="check sfi"><input type="checkbox" ${st.cats.includes(c.id)?'checked':''} data-chg="sfCat" data-ctx="${ctx}" data-id="${c.id}" style="accent-color:var(--primary)"><span class="sfl">${c.e} ${esc(nm(c))}</span><span class="sfn">${n}</span></label>`}).join('')}</div></div>`;
 h+=`<div class="sfsec"><h4>${t('Subcategory')}</h4>`;
 if(!st.cats.length)h+=`<div class="small muted">${t('Pick a category above to see its subcategories.')}</div>`;
 else st.cats.forEach(cid=>{const all=svcSubs(cid),key=ctx+':'+cid,q=(UI.sfq[key]||'').toLowerCase(),items=all.filter(x=>!q||(x.en+' '+x.hi).toLowerCase().includes(q)),cnt=x=>base.filter(b=>b.cat===cid&&(b.ssubs||[]).includes(x.slug)).length;
  h+=`<div class="sfgrp" role="group" aria-label="${esc(catName(cid))}"><div class="row between" style="gap:6px"><b class="small">${catOf(cid).e} ${esc(catName(cid))}</b><span class="row" style="gap:0"><button type="button" class="btn t sm" style="min-height:36px;padding:0 8px" data-act="sfAll" data-ctx="${ctx}" data-cat="${cid}">${t('Select all')}</button><button type="button" class="btn t sm" style="min-height:36px;padding:0 8px" data-act="sfClr" data-ctx="${ctx}" data-cat="${cid}">${t('Clear')}</button></span></div>${all.length>8?`<div class="searchbar" style="min-height:42px;margin:6px 0">${ic('search',16)}<input data-in="sfq" data-ctx="${ctx}" data-cat="${cid}" value="${esc(UI.sfq[key]||'')}" placeholder="${t('Search subcategories')}" aria-label="${t('Search subcategories')} ${esc(catName(cid))}"></div>`:''}<div class="stack" style="gap:2px">${items.map(x=>{const n=cnt(x);return `<label class="check sfi ${n?'':'dis'}"><input type="checkbox" ${st.subs.includes(x.slug)?'checked':''} ${n||st.subs.includes(x.slug)?'':'disabled'} data-chg="sfSub" data-ctx="${ctx}" data-s="${x.slug}" style="accent-color:var(--primary)"><span class="sfl">${esc(S.lang==='hi'&&x.hi?x.hi:x.en)}</span><span class="sfn">${n}</span></label>`}).join('')||`<div class="small muted" style="padding:6px">${t('No match')}</div>`}</div></div>`});
 return h+'</div></div>'}
const svcFilterCard=ctx=>`<details class="acc" open><summary>${t('Category & subcategory')}${ic('cd',18)}</summary><div>${svcSubFilter(ctx,{cats:true})}</div></details>`;
function sfRedraw(ctx){const act=document.activeElement,root=act&&act.closest&&act.closest('.sf');const nodes=$$('.sf[data-ctx="'+ctx+'"]'),ci=nodes.indexOf(root);const sel=act&&act.dataset?(act.dataset.s?`[data-s="${act.dataset.s}"]`:act.dataset.id?`[data-id="${act.dataset.id}"]`:act.dataset.in==='sfq'?`[data-in=sfq][data-cat="${act.dataset.cat}"]`:act.dataset.act?`[data-act=${act.dataset.act}][data-cat="${act.dataset.cat}"]`:''):'';const pos=act&&act.selectionStart;
 const o={cats:!!nodes[0]&&!!nodes[0].querySelector('[data-chg=sfCat]')};nodes.forEach(n=>{const own=!!n.querySelector('[data-chg=sfCat]');n.outerHTML=svcSubFilter(ctx,{cats:own})});if(ci>=0&&sel){const n2=$$('.sf[data-ctx="'+ctx+'"]')[ci],e=n2&&n2.querySelector(sel);if(e){e.focus();if(pos!=null&&e.setSelectionRange)try{e.setSelectionRange(pos,pos)}catch(_){}}}}
function sfRedrawAll(){['ex','srch','cat','prev'].forEach(c=>{if($('.sf[data-ctx="'+c+'"]'))sfRedraw(c)})}
const skelRes=()=>`<div class="stack" aria-busy="true" aria-label="${t('Loading')}"><div class="skel" style="height:22px;width:40%"></div><div class="grid auto"><div class="skel" style="height:120px"></div><div class="skel" style="height:120px"></div><div class="skel" style="height:120px"></div></div></div>`;
function sfApply(ctx){sfRedraw(ctx);
 if(ctx==='ex'||ctx==='srch'){exSync();const box=ctx==='ex'?$('#exres'):$('#results');if(box){box.innerHTML=skelRes();clearTimeout(UI.sfT);UI.sfT=setTimeout(()=>{if(ctx==='ex')exRefresh();else{$('#results').innerHTML=resultsHtml();sfRedraw('srch')}},S.demo.slow?700:180)}}
 else if(ctx==='cat'){const b=$('#csres');if(b){b.innerHTML=skelRes();clearTimeout(UI.sfT);UI.sfT=setTimeout(()=>{const x=$('#csres');x&&(x.innerHTML=catResHtml(UI.cfId))},180)}}
 else if(ctx==='prev'){prevRefresh()}}
CH.sfCat=el=>{const st=sfState(el.dataset.ctx);svcToggleCat(st,el.dataset.id,el.checked);sfApply(el.dataset.ctx)};
CH.sfSub=el=>{const st=sfState(el.dataset.ctx),s=el.dataset.s;st.subs=el.checked?[...new Set([...st.subs,s])]:st.subs.filter(x=>x!==s);sfApply(el.dataset.ctx)};
A.sfAll=el=>{const ctx=el.dataset.ctx,st=sfState(ctx),base=sfBase(ctx);const add=svcSubs(el.dataset.cat).filter(x=>base.some(b=>b.cat===el.dataset.cat&&(b.ssubs||[]).includes(x.slug))).map(x=>x.slug);st.subs=[...new Set([...st.subs,...add])];sfApply(ctx)};
A.sfClr=el=>{const ctx=el.dataset.ctx,st=sfState(ctx);st.subs=st.subs.filter(s=>subCat(s)!==el.dataset.cat);sfApply(ctx)};
INP.sfq=(v,el)=>{UI.sfq[el.dataset.ctx+':'+el.dataset.cat]=v;sfRedraw(el.dataset.ctx)};
/* ---- URL state ---- */
const TABN={p:'products',b:'shops',s:'services'},TABK={products:'p',shops:'b',services:'s'};
function exSync(){if(cur().name!=='explore')return;const f=UI.exF[UI.exTab],q=new URLSearchParams();q.set('tab',TABN[UI.exTab]);if(UI.exTab==='s'){if(f.cats.length)q.set('category',f.cats.map(catSlug).join(','));if(f.subs.length)q.set('subcategory',f.subs.join(','))}else if(f.cat)q.set('category',slug((catOf(f.cat)||{en:f.cat}).en));try{history.replaceState(null,'',location.pathname+'?'+q.toString().replace(/%2C/g,',')+'#explore')}catch(e){}}
function applyQuery(){try{const q=new URLSearchParams(location.search),tb=TABK[q.get('tab')];if(!tb)return;UI.exTab=tb;UI.exF[tb]={...exDef(tb)};const cs=(q.get('category')||'').split(',').filter(Boolean);if(tb==='s'){UI.exF.s.cats=cs.map(slugCat).filter(Boolean);UI.exF.s.subs=(q.get('subcategory')||'').split(',').filter(x=>x&&subInfo(x)&&UI.exF.s.cats.includes(subCat(x)))}else if(cs[0]){const c=[...CATS,...SCATS].find(x=>slug(x.en)===cs[0]||x.id===cs[0]);if(c)UI.exF[tb].cat=c.id}}catch(e){}}
A.exCopy=()=>{exSync();const u=location.href;try{navigator.clipboard.writeText(u).then(()=>toast(t('Link copied'),'copy'),()=>toast(u,'info'))}catch(e){toast(u,'info')}};
