function catResHtml(id){const f=UI.cf,l=svcApplyCS(D().svc.filter(s=>s.cat===id&&s.status==='approved'),f).sort((a,b)=>dist(a)-dist(b));const chips=f.subs;
 return `<div class="row between wrap-r"><b aria-live="polite">${l.length} ${t('services')}</b>${chips.length?`<button class="btn t sm" data-act="cfClear">${t('Clear all')}</button>`:''}</div>${chips.length?`<div class="row wrap-r" style="gap:6px">${chips.map(x=>`<button class="rchip" data-act="cfRm" data-s="${x}" aria-label="${t('Remove filter')}: ${esc(subLabel(x))}">${esc(subLabel(x))} <b>${ic('x',14)}</b></button>`).join('')}</div>`:''}${l.length?`<div class="grid auto">${l.map(x=>svcCard(x)).join('')}</div>`:empty('🔎','No services match','Try removing a subcategory.','<button class="btn p" data-act="cfClear">'+t('Clear all')+'</button>')}`}
const _catPage=V.cat;V.cat=id=>{if(!SCATS.some(x=>x.id===id))return _catPage(id);if(UI.cfId!==id){UI.cfId=id;UI.cf={cats:[id],subs:[]}}const c=catOf(id);
 return `<div class="stack-lg"><div class="crumb"><a href="#home">${t('Home')}</a> / <span>${esc(nm(c))}</span></div><div class="row between wrap-r"><div class="row"><div class="art mini" style="--h:${c.h}">${c.e}</div><h1>${esc(nm(c))}</h1></div><button class="btn p sm" data-act="exGo" data-tab="s" data-pre='${esc(JSON.stringify({cats:[id]}))}'>${t('Explore Services')} ${ic('cr',14)}</button></div><div class="exlay"><aside class="card pad exside2">${svcSubFilter('cat',{cats:false})}</aside><div id="csres" class="stack">${catResHtml(id)}</div></div></div>`};
A.cfRm=el=>{UI.cf.subs=UI.cf.subs.filter(x=>x!==el.dataset.s);sfApply('cat')};A.cfClear=()=>{UI.cf.subs=[];sfApply('cat')};
