function pfSubs(cat,sel){const l=svcSubs(cat);return l.length?`<div class="stack" style="gap:2px"><b class="small">${catOf(cat).e} ${esc(catName(cat))}</b>${l.map(x=>`<label class="check sfi"><input type="checkbox" name="ss_${x.slug}" ${sel.includes(x.slug)?'checked':''} style="accent-color:var(--primary)"><span class="sfl">${esc(S.lang==='hi'&&x.hi?x.hi:x.en)}</span></label>`).join('')}</div>`:`<span class="muted small">${t('No subcategories yet.')}</span>`}
document.addEventListener('change',e=>{const el=e.target;if(el.name==='cat'&&el.closest('form[data-form=sprof]')){const c=$('#pfsubs');if(c){const keep=$$('#pfsubs input:checked').map(i=>i.name.slice(3));c.innerHTML=pfSubs(el.value,keep.filter(k=>subCat(k)===el.value))}}});
